select public.tutorial_save_article($j${"article":{"slug":"masuk-dengan-akun-7mit","service_slug":"akun","category_slug":"akun-keamanan","title_id":"Masuk dengan akun 7 MIT","title_en":"Sign in with your 7 MIT account","summary_id":"Langkah masuk memakai nama pengguna atau Google, termasuk jika ada nama pengguna ganda.","summary_en":"How to sign in with a username or Google, including duplicate usernames.","status":"published","verified":true,"featured":true,"popular":true,"minutes":3,"created_at":"2026-11-11T03:00:00Z","updated_at":"2026-11-11T03:00:00Z"},"services":["akun"],"blocks":[{"kind":"text","items":[],"text_id":"Anda bisa masuk dengan nama pengguna dan kata sandi, atau dengan Google. Simulasi di bawah hanya contoh: ia tidak meminta atau menyimpan kata sandi Anda.","text_en":"You can sign in with a username and password, or with Google. The simulation below is only a demo: it never asks for or stores your password."},{"kind":"steps","items":[{"role":"step","label_id":"Buka akun.7mit.org","label_en":"Open akun.7mit.org","text_id":"Gunakan alamat resmi dan pastikan ada tanda gembok di peramban.","text_en":"Use the official address and check for the padlock in your browser.","hint_id":"","hint_en":""},{"role":"step","label_id":"Isi nama pengguna","label_en":"Enter your username","text_id":"Contoh: contoh atau contoh@7mit. Keduanya diterima.","text_en":"Example: contoh or contoh@7mit. Both are accepted.","hint_id":"","hint_en":""},{"role":"step","label_id":"Isi kata sandi lalu Masuk","label_en":"Enter password and sign in","text_id":"Kata sandi diketik hanya di halaman resmi.","text_en":"Type your password only on the official page.","hint_id":"","hint_en":""},{"role":"step","label_id":"Pilih akun bila diminta","label_en":"Choose the account if asked","text_id":"Jika nama pengguna dipakai lebih dari satu akun, server meminta Anda memilih.","text_en":"If a username belongs to more than one account, the server asks you to choose.","hint_id":"Pilih sesuai peran An